<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import FinanceDialog from './FinanceDialog.vue';
import FinancePagination from './FinancePagination.vue';
import {accountTypes} from './finance-model.js';
const props=defineProps({modelValue:[String,Number],disabled:Boolean,vm:{type:Object,required:true},parameters:{type:Object,default:()=>({})},label:{type:String,default:'الحساب'},clearable:{type:Boolean,default:true}}),emit=defineEmits(['update:modelValue','selected']);
const open=ref(false),query=ref(''),rows=ref([]),meta=ref({current_page:1,last_page:1,total:0}),loading=ref(false),error=ref('');let reader,timer,resolver,resolveRevision=0,revision=0,alive=true,mounted=false;
const selected=computed(()=>props.vm.options.accounts.find(row=>Number(row.id)===Number(props.modelValue)));
async function resolveSelection(){if(!mounted||!props.modelValue||selected.value)return;resolver?.abort();resolver=new AbortController();const expected=++resolveRevision,id=props.modelValue;try{const result=await props.vm.api.list('accounts',{...props.parameters,account_id:id,per_page:1},resolver.signal);if(alive&&expected===resolveRevision&&props.modelValue===id)props.vm.rememberAccounts(result.data);}catch(failed){if(alive&&expected===resolveRevision&&failed.name!=='AbortError')error.value=await props.vm.failure(failed);}}
onMounted(()=>{mounted=true;resolveSelection();});watch(()=>props.modelValue,resolveSelection);watch(()=>props.vm.options.accounts,resolveSelection);
async function load(page=1){reader?.abort();reader=new AbortController();const expected=++revision;loading.value=true;error.value='';try{const result=await props.vm.api.list('accounts',{...props.parameters,account_query:query.value||props.parameters.account_query,per_page:25,page},reader.signal);if(alive&&expected===revision){rows.value=result.data;meta.value=result.meta;props.vm.rememberAccounts(result.data);}}catch(failed){if(failed.name!=='AbortError'&&alive&&expected===revision)error.value=await props.vm.failure(failed);}finally{if(alive&&expected===revision)loading.value=false;}}
function choose(row){props.vm.rememberAccounts([row]);emit('update:modelValue',row.id);emit('selected',row);open.value=false;}
watch(open,value=>{if(value){query.value='';load();}else{revision++;reader?.abort();}});
watch(query,()=>{clearTimeout(timer);timer=setTimeout(()=>{if(open.value)load();},300);});
watch(()=>props.parameters,()=>{if(open.value)load();},{deep:true});
onBeforeUnmount(()=>{alive=false;revision++;resolveRevision++;resolver?.abort();reader?.abort();clearTimeout(timer);});
</script>
<template><div class="finance-account-picker"><button type="button" class="btn account-picker-trigger" :aria-label="label" aria-haspopup="dialog" :disabled="disabled" @click="open=true">{{selected?.name|| (modelValue?'#'+modelValue:'اختر الحساب')}} <span aria-hidden="true">⌄</span></button><FinanceDialog :open="open" :title="label" @close="open=false"><label>بحث بالاسم أو الهاتف<input v-model="query" type="search" autocomplete="off" :aria-label="'بحث '+label"></label><p v-if="error" class="notice warn" role="alert">{{error}}</p><p v-if="loading" role="status">جارٍ تحميل الحسابات…</p><div class="account-picker-results"><button v-if="clearable" type="button" class="btn" @click="emit('update:modelValue','');open=false">الكل / مسح الاختيار</button><button v-for="row in rows" :key="row.id" type="button" class="btn" @click="choose(row)"><strong>{{row.name}}</strong><small>{{accountTypes[row.type]}} · {{row.phone||row.city||'#'+row.id}}</small></button><p v-if="!loading&&!error&&!rows.length">لا توجد حسابات مطابقة</p></div><FinancePagination :meta="meta" :busy="loading" @page="load"/></FinanceDialog></div></template>
<style scoped>.account-picker-trigger{width:100%;display:flex;justify-content:space-between;min-height:42px}.account-picker-results{display:flex;flex-direction:column;gap:6px;margin-block:12px;max-height:45vh;overflow:auto}.account-picker-results .btn{display:flex;justify-content:space-between;gap:12px;text-align:start}.account-picker-results small{color:var(--muted,#7892a2)}</style>
